//! 📖️ Actual continuous-tool ledgers lend one native state under its original Job and decoder.
use super::*;
use semio_framework_value::{retirement::RetireOwned,SharedUtf8};
use semio_framework_value::retained_clone::{original_slot::RetainedOriginalSlotKey,RetainedCloneClose,RetainedCloneRef};
use semio_framework_tool_machine::OriginalToolLedgerSource;
use semio_framework_job::OriginalSourceBinding;
type Issuer<S>=Arc<dyn semio_framework_value::ArtifactOwnedValueRetirementFactory<S>>;
/// 🔗️ A source owner keeps its actual resident key, immutable issuer and original caller until return.
pub struct OriginalToolLedgerRead<S:RetireOwned+Send+Sync+'static>{binding:Option<OriginalSourceBinding>,decoder:Option<Decoder>,revision:u64,window:Option<SharedUtf8>,key:Option<RetainedOriginalSlotKey>,factory:Option<Issuer<S>>,returned_factory:Option<Issuer<S>>,factory_close:Option<FactoryAuthority>,retirement:RetainedCloneClose,read_reply:Option<Result<RetainedCloneStep,semio_framework_value::OriginalRetirementFailure>>,return_reply:Option<Result<RetainedCloneStep,semio_framework_value::OriginalRetirementFailure>>,read_pending:bool,return_pending:bool,ready:bool,returned:bool,closing:bool}
impl<S:RetireOwned+Send+Sync+'static> Default for OriginalToolLedgerRead<S>{fn default()->Self{Self{binding:None,decoder:None,revision:0,window:None,key:None,factory:None,returned_factory:None,factory_close:None,retirement:Default::default(),read_reply:None,return_reply:None,read_pending:false,return_pending:false,ready:false,returned:false,closing:false}}}
impl<S:RetireOwned+Send+Sync+'static> OriginalToolLedgerRead<S>{
 fn validate(&self,cx:&StepContext<'_>)->Result<(),ValueError>{if !self.binding.is_some_and(|binding|binding.matches(cx))||cx.native_receiving_identity()!=self.decoder{return Err(invalid("original tool state read changed its caller or decoder"))}Ok(())}
 /// 📏️ Quotes the authentic resident alias and source fence before any admission.
 pub fn admission_demands()->RetirementDemand{header::<(OriginalSourceBinding,Decoder,u64,SharedUtf8,RetainedOriginalSlotKey)>()}
 /// 📥️ Captures the same declared resident instead of materializing its variable state or leaves.
 pub fn admit<L:OriginalToolLedgerSource<State=S>>(&mut self,ledger:&L,window:&SharedUtf8,key:RetainedOriginalSlotKey,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if self.binding.is_some()||self.closing||!ledger.original_live(window,key)?{return Err(invalid("original tool state read requires its live resident and empty recipient").into())}let binding=OriginalSourceBinding::borrow(cx);let d=Self::admission_demands();let mut done=None;built_with(cx,&mut done,OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth},|identity|{let decoder=identity.ok_or_else(||invalid("original tool state read requires its actual decoder recipient"))?;self.binding=Some(binding);self.decoder=Some(decoder);self.revision=ledger.original_revision();self.window=Some(window.clone());self.key=Some(key);Ok(((),RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))})?;Ok(done.is_some())}
 fn issuer_demand()->RetirementDemand{type Factory<S>=semio_framework_value::factory::OwnedValueRetirementFactory<S>;RetirementDemand{copy_bytes:size_of::<Factory<S>>()+2*size_of::<Issuer<S>>(),capacity_bytes:semio_framework_value::shared_retirement_allocation_bytes::<Factory<S>>(),depth:1,..Default::default()}}
 /// 📏️ Quotes the next original issuer or immutable state-source birth.
 pub fn demands<L:OriginalToolLedgerSource<State=S>>(&self,ledger:&L,body:usize)->Result<RetirementDemand,ValueError>{if self.closing{return self.close_demands(ledger,body)}if self.binding.is_none(){return Ok(Self::admission_demands())}if self.ready{return Ok(Default::default())}if self.factory.is_none(){return Ok(Self::issuer_demand())}let mut d=ledger.original_read_demands(self.window.as_ref().unwrap(),self.key.unwrap(),body)?;d.copy_bytes+=size_of::<bool>();Ok(d)}
 /// 🪜️ The actual ledger retains its original state and captured issuer while the reader is issued.
 pub fn advance<L:OriginalToolLedgerSource<State=S>>(&mut self,ledger:&mut L,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if self.closing||ledger.original_revision()!=self.revision{return Err(invalid("original tool state read requires its unchanged source frontier").into())}if self.ready{return Ok(true)}let d=self.demands(ledger,4096)?;if self.factory.is_none(){paid(cx,d,|_|{self.factory=Some(Arc::new(semio_framework_value::factory::OwnedValueRetirementFactory::<S>::default()));Ok(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,..Default::default()})})?;return Ok(false)}paid_effect(cx,d,|effect|{
  if self.read_reply.is_none(){let reply=semio_framework_value::retained_clone::OriginalEffectReply::borrow(&mut self.read_reply)?;let(window,key,factory)=(self.window.as_ref().unwrap(),self.key.unwrap(),self.factory.as_ref().unwrap());let done=if self.read_pending{ledger.recover_original_read_advance_into(window,key,factory,effect,reply)?}else{ledger.original_read_advance_into(window,key,factory,effect,reply)?};drop(done);}
  let Some(result)=self.read_reply.take()else{self.read_pending=true;return Ok(Default::default())};self.read_pending=false;
  let step=result.map_err(semio_framework_value::OriginalRetirementFailure::into_value_error)?;if matches!(step,RetainedCloneStep::Complete(_)){self.ready=true;}let mut p=step.progress();p.copied_items=p.copied_items.max(1);p.copied_bytes+=size_of::<bool>();Ok(p)
 })?;Ok(self.ready)}
 /// 📖️ Borrows the original immutable native state while its authentic resident source remains issued.
 pub fn borrow<'a,L:OriginalToolLedgerSource<State=S>>(&self,ledger:&'a L)->Result<RetainedCloneRef<'a,S>,ValueError>{if !self.ready||self.closing||ledger.original_revision()!=self.revision{return Err(invalid("original tool state source is incomplete or moved"))}ledger.original_read(self.window.as_ref().unwrap(),self.key.unwrap())}
 /// ✅️ Readiness never donates or copies the original row.
 pub fn ready(&self)->bool{self.ready&&!self.closing}
 /// 📏️ Closure keeps the same resident and factory even when another window moves the global source frontier.
 pub fn close_demands<L:OriginalToolLedgerSource<State=S>>(&self,ledger:&L,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Ok(if self.binding.is_none(){header::<(bool,bool)>()}else{header::<bool>()})}if !self.returned{let mut d=ledger.original_return_demands(self.window.as_ref().unwrap(),self.key.unwrap(),body)?;d.copy_bytes+=size_of::<bool>();return Ok(d)}if let Some(owner)=self.factory_close.as_ref(){return if owner.terminal_is_empty(){Ok(header::<Option<FactoryAuthority>>())}else{owner.demands(body)}}if self.returned_factory.is_some()||self.factory.is_some(){return Ok(header::<(Issuer<S>,FactoryAuthority)>())}if !self.retirement.is_empty()||self.window.is_some(){return self.retirement.next_owner_demands::<SharedUtf8>(self.window.is_some(),&None,body)}if self.binding.is_some(){return Ok(header::<(Option<OriginalSourceBinding>,Option<Decoder>,Option<RetainedOriginalSlotKey>)>())}Ok(Default::default())}
 /// ♻️ Returns every actual state lease before closing its captured issuers and original window alias.
 pub fn close_step<L:OriginalToolLedgerSource<State=S>>(&mut self,ledger:&mut L,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if self.terminal_is_empty(){return Ok(true)}if self.binding.is_none()&&!self.closing{let d=header::<(bool,bool)>();close_paid(cx,d,|_|{self.closing=true;self.returned=true;Ok(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()})})?;return Ok(self.terminal_is_empty())}self.validate(cx)?;let d=self.close_demands(ledger,4096)?;if !self.closing{close_paid(cx,d,|_|{self.closing=true;Ok(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()})})?;return Ok(false)}if !self.returned{semio_framework_job::close_original_effect_step(cx,d,|effect|{
  let before=effect.performed_work();
  if self.return_reply.is_none(){let reply=match semio_framework_value::retained_clone::OriginalEffectReply::borrow(&mut self.return_reply){Ok(reply)=>reply,Err(error)=>return settled_poll(semio_framework_value::RetainedWorkOutcome{result:Err(error),work:effect.performed_work()-before})};let(window,key)=(self.window.as_ref().unwrap(),self.key.unwrap());let done=if self.return_pending{ledger.recover_original_return_into(window,key,&mut self.returned_factory,effect,reply)}else{ledger.original_return_into(window,key,&mut self.returned_factory,effect,reply)};if let Err(error)=done{return settled_poll(semio_framework_value::RetainedWorkOutcome{result:Err(error),work:effect.performed_work()-before})}}
  let work=effect.performed_work()-before;
  let result=match self.return_reply.take(){None=>{self.return_pending=true;Ok(RetainedCloneStep::Progress(Default::default()))},Some(result)=>{self.return_pending=false;if matches!(result,Ok(RetainedCloneStep::Complete(_))){self.returned=true;}result.map_err(semio_framework_value::OriginalRetirementFailure::into_value_error)}};
  settled_poll(semio_framework_value::RetainedWorkOutcome{result,work})
 })?;return Ok(false)}if let Some(owner)=self.factory_close.as_mut(){if owner.terminal_is_empty(){close_paid(cx,d,|_|{self.factory_close=None;Ok(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()})})?;}else{semio_framework_job::close_original_effect_step(cx,d,|effect|owner.step(4096,effect))?;}return Ok(false)}if self.returned_factory.is_some()||self.factory.is_some(){close_paid(cx,d,|_|{let factory=self.returned_factory.take().or_else(||self.factory.take()).unwrap();self.factory_close=Some(FactoryAuthority::new(factory));Ok(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()})})?;return Ok(false)}if !self.retirement.is_empty()||self.window.is_some(){semio_framework_job::close_original_effect_step(cx,d,|effect|{if !self.retirement.is_empty(){self.retirement.step_granted(4096,effect)}else{let turn=self.retirement.begin_granted(&mut self.window,effect);settled_poll(semio_framework_value::RetainedWorkOutcome{result:turn.result.map(|step|step.unwrap_or(RetainedCloneStep::Progress(Default::default()))),work:turn.work})}})?;return Ok(false)}if self.binding.is_some(){close_paid(cx,d,|_|{self.binding=None;self.decoder=None;self.key=None;Ok(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()})})?;return Ok(false)}Ok(true)}
 /// 🧺️ Terminal custody includes the issued state, both original issuer aliases and the resident address.
 pub fn terminal_is_empty(&self)->bool{self.closing&&self.returned&&self.binding.is_none()&&self.key.is_none()&&self.window.is_none()&&self.factory.is_none()&&self.returned_factory.is_none()&&self.factory_close.is_none()&&self.retirement.is_empty()&&!self.read_pending&&!self.return_pending&&self.read_reply.is_none()&&self.return_reply.is_none()}
}
impl<S:RetireOwned+Send+Sync+'static> Drop for OriginalToolLedgerRead<S>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty()||self.binding.is_none()&&!self.closing,"original tool state reader requires original funded closure")}}

